import sys
from collections import defaultdict

MOD = 1_000_000_007

def count_orderings(names):
    def group_by_prefix(names):
        groups = defaultdict(list)
        for name in names:
            for i in range(1, len(name) + 1):
                prefix = name[:i]
                groups[prefix].append(name)
        return groups

    def count_ways_to_order(group):
        if len(group) <= 1:
            return 1
        group.sort()
        ways = 1
        for i in range(1, len(group)):
            if group[i].startswith(group[i - 1]):
                ways = (ways * (i + 1)) % MOD
        return ways

    groups = group_by_prefix(names)
    total_ways = 1
    for group in groups.values():
        total_ways = (total_ways * count_ways_to_order(group)) % MOD

    return total_ways

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    names = data[1:]
    result = count_orderings(names)
    print(result)

if __name__ == "__main__":
    main()
